    private static readonly JsonSerializerOptions JsonOptions=new(JsonSerializerDefaults.Web);
    public async Task<WindowsApplicationSource?>FindSourceAsync(string providerId,string providerItemId,CancellationToken cancellationToken=default){await using SqliteConnection c=await factory.OpenAsync(cancellationToken).ConfigureAwait(false);await using SqliteCommand cmd=c.CreateCommand();cmd.CommandText="SELECT * FROM WindowsApplicationSources WHERE ProviderId=$provider AND ProviderItemId=$item;";Add(cmd,"$provider",providerId);Add(cmd,"$item",providerItemId);await using SqliteDataReader r=await cmd.ExecuteReaderAsync(cancellationToken).ConfigureAwait(false);return await r.ReadAsync(cancellationToken).ConfigureAwait(false)?ReadSource(r):null;}
    public async Task<IReadOnlyList<WindowsApplicationSource>>GetSourcesAsync(string? providerId=null,CancellationToken cancellationToken=default){await using SqliteConnection c=await factory.OpenAsync(cancellationToken).ConfigureAwait(false);await using SqliteCommand cmd=c.CreateCommand();cmd.CommandText=providerId is null?"SELECT * FROM WindowsApplicationSources ORDER BY ProviderId,ProviderItemId;":"SELECT * FROM WindowsApplicationSources WHERE ProviderId=$provider ORDER BY ProviderItemId;";if(providerId is not null)Add(cmd,"$provider",providerId);List<WindowsApplicationSource> result=[];await using SqliteDataReader r=await cmd.ExecuteReaderAsync(cancellationToken).ConfigureAwait(false);while(await r.ReadAsync(cancellationToken).ConfigureAwait(false))result.Add(ReadSource(r));return result;}
    public async Task<WindowsApplicationSource?>GetSourceForItemAsync(string libraryItemId,CancellationToken cancellationToken=default){await using SqliteConnection c=await factory.OpenAsync(cancellationToken).ConfigureAwait(false);await using SqliteCommand cmd=c.CreateCommand();cmd.CommandText="SELECT * FROM WindowsApplicationSources WHERE LibraryItemId=$id ORDER BY Installed DESC,DiscoveryConfidence DESC LIMIT 1;";Add(cmd,"$id",libraryItemId);await using SqliteDataReader r=await cmd.ExecuteReaderAsync(cancellationToken).ConfigureAwait(false);return await r.ReadAsync(cancellationToken).ConfigureAwait(false)?ReadSource(r):null;}

    public async Task<WindowsApplicationImportPreview>CreatePreviewAsync(IReadOnlyCollection<WindowsApplicationCandidate> candidates,IWindowsApplicationClassifier classifier,CancellationToken cancellationToken=default)
    {
        await using SqliteConnection c=await factory.OpenAsync(cancellationToken).ConfigureAwait(false);List<WindowsApplicationPreviewCandidate> result=[];
        foreach(WindowsApplicationCandidate candidate in candidates){cancellationToken.ThrowIfCancellationRequested();WindowsApplicationClassification classification=classifier.Classify(candidate);string? validation=Validate(candidate);(string? item,bool exact)=await FindDuplicateAsync(c,candidate,cancellationToken).ConfigureAwait(false);WindowsImportStatus status=validation is not null?WindowsImportStatus.Invalid:classification.Kind switch{WindowsCandidateKind.RelatedTool=>WindowsImportStatus.RelatedTool,WindowsCandidateKind.PossibleUninstaller=>WindowsImportStatus.PossibleUninstaller,_ when exact=>WindowsImportStatus.AlreadyImported,_ when item is not null=>WindowsImportStatus.PossibleDuplicate,_ when !candidate.Installed=>WindowsImportStatus.Missing,_=>WindowsImportStatus.New};bool selected=status==WindowsImportStatus.New&&classification.SelectedByDefault;result.Add(new(candidate,classification,status,selected,item,validation));}
        return new(result,[],DateTime.UtcNow);
    }

    public async Task<WindowsApplicationImportResult>ImportAsync(IReadOnlyCollection<WindowsApplicationImportSelection> selections,CancellationToken cancellationToken=default)
    {
        int added=0,updated=0,linked=0,alternate=0,skipped=0,failed=0;List<string>errors=[];await using SqliteConnection c=await factory.OpenAsync(cancellationToken).ConfigureAwait(false);await using SqliteTransaction tx=(SqliteTransaction)await c.BeginTransactionAsync(cancellationToken).ConfigureAwait(false);
        foreach(WindowsApplicationImportSelection selection in selections){cancellationToken.ThrowIfCancellationRequested();if(selection.Action==WindowsImportAction.Skip){skipped++;continue;}await ExecuteAsync(c,tx,"SAVEPOINT windows_item;",cancellationToken).ConfigureAwait(false);try{WindowsApplicationCandidate candidate=selection.Candidate.Candidate;string? existingSource=await ScalarAsync(c,tx,"SELECT LibraryItemId FROM WindowsApplicationSources WHERE ProviderId=$provider AND ProviderItemId=$item;",cmd=>{Add(cmd,"$provider",candidate.ProviderId);Add(cmd,"$item",candidate.ProviderItemId);},cancellationToken).ConfigureAwait(false);if(existingSource is not null){await UpdateSourceAsync(c,tx,candidate,cancellationToken).ConfigureAwait(false);updated++;await ExecuteAsync(c,tx,"RELEASE windows_item;",cancellationToken).ConfigureAwait(false);continue;}string itemId=selection.ExistingLibraryItemId??Guid.NewGuid().ToString("N");bool newItem=selection.ExistingLibraryItemId is null||selection.Action==WindowsImportAction.ImportSeparately;if(newItem){itemId=Guid.NewGuid().ToString("N");await InsertItemAsync(c,tx,itemId,candidate,cancellationToken).ConfigureAwait(false);added++;}else if(selection.Action==WindowsImportAction.AddAlternateLaunchTarget)alternate++;else linked++;string sourceId=Guid.NewGuid().ToString("N");await InsertWindowsSourceAsync(c,tx,sourceId,itemId,candidate,cancellationToken).ConfigureAwait(false);await InsertGenericSourceAsync(c,tx,itemId,candidate,cancellationToken).ConfigureAwait(false);await InsertLaunchTargetAsync(c,tx,Guid.NewGuid().ToString("N"),sourceId,itemId,candidate,cancellationToken).ConfigureAwait(false);if(newItem||selection.CategoryId is not null)await SetCategoryAsync(c,tx,itemId,selection.CategoryId??CategoryId(selection.Candidate.Classification.SuggestedCategory),ApplicationCategorySource.Automatic,cancellationToken).ConfigureAwait(false);await UpsertTrackingAsync(c,tx,itemId,candidate,cancellationToken).ConfigureAwait(false);if(selection.DesktopControlProfileId is not null)await UpsertAssignmentAsync(c,tx,new(itemId,selection.DesktopControlProfileId,selection.EnableDesktopControlOnLaunch),cancellationToken).ConfigureAwait(false);if(candidate.IconCandidate is not null)await InsertIconAsync(c,tx,itemId,candidate.IconCandidate,cancellationToken).ConfigureAwait(false);await ExecuteAsync(c,tx,"RELEASE windows_item;",cancellationToken).ConfigureAwait(false);}catch(Exception exception)when(exception is SqliteException or IOException or UnauthorizedAccessException or InvalidOperationException){await ExecuteAsync(c,tx,"ROLLBACK TO windows_item; RELEASE windows_item;",CancellationToken.None).ConfigureAwait(false);failed++;errors.Add($"{selection.Candidate.Candidate.DisplayName}: {exception.Message}");}}
        await tx.CommitAsync(cancellationToken).ConfigureAwait(false);return new(added,updated,linked,alternate,skipped,failed,errors);
    }

    public async Task ApplyRefreshAsync(WindowsApplicationScanResult scan,CancellationToken cancellationToken=default)
    {
        if(scan.WasCancelled||!scan.CompletedSuccessfully)return;await using SqliteConnection c=await factory.OpenAsync(cancellationToken).ConfigureAwait(false);await using SqliteTransaction tx=(SqliteTransaction)await c.BeginTransactionAsync(cancellationToken).ConfigureAwait(false);DateTime now=DateTime.UtcNow;
        string[] providerIds=string.Equals(scan.ProviderId,"windows-applications",StringComparison.OrdinalIgnoreCase)?["windows-start-menu","windows-apps-folder","windows-pwa"]:[scan.ProviderId];
        foreach(string providerId in providerIds){WindowsApplicationCandidate[] current=scan.Candidates.Where(value=>string.Equals(value.ProviderId,providerId,StringComparison.OrdinalIgnoreCase)).ToArray();HashSet<string>present=current.Select(value=>value.ProviderItemId).ToHashSet(StringComparer.OrdinalIgnoreCase);foreach(WindowsApplicationCandidate candidate in current)await UpdateSourceAsync(c,tx,candidate,cancellationToken).ConfigureAwait(false);await using SqliteCommand read=c.CreateCommand();read.Transaction=tx;read.CommandText="SELECT Id,ProviderItemId,LibraryItemId FROM WindowsApplicationSources WHERE ProviderId=$provider;";Add(read,"$provider",providerId);List<(string Id,string ProviderItem,string LibraryItem)>stored=[];await using(SqliteDataReader r=await read.ExecuteReaderAsync(cancellationToken).ConfigureAwait(false)){while(await r.ReadAsync(cancellationToken).ConfigureAwait(false))stored.Add((r.GetString(0),r.GetString(1),r.GetString(2)));}foreach(var source in stored.Where(value=>!present.Contains(value.ProviderItem))){await using SqliteCommand missing=c.CreateCommand();missing.Transaction=tx;missing.CommandText="UPDATE WindowsApplicationSources SET Installed=0,LastSeenAtUtc=$now WHERE Id=$id; UPDATE LibraryItemSources SET Installed=0,LastSeenAtUtc=$now WHERE ProviderId=$provider AND ProviderItemId=$providerItem; UPDATE LaunchTargets SET IsEnabled=0,UpdatedAtUtc=$now WHERE WindowsApplicationSourceId=$id AND UserManaged=0;";Add(missing,"$now",now.ToString("O"));Add(missing,"$id",source.Id);Add(missing,"$provider",providerId);Add(missing,"$providerItem",source.ProviderItem);await missing.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);}}
        await tx.CommitAsync(cancellationToken).ConfigureAwait(false);
    }

    public async Task<IReadOnlyList<ApplicationCategory>>GetCategoriesAsync(CancellationToken cancellationToken=default){await using SqliteConnection c=await factory.OpenAsync(cancellationToken).ConfigureAwait(false);await using SqliteCommand cmd=c.CreateCommand();cmd.CommandText="SELECT * FROM ApplicationCategories ORDER BY SortOrder,Name;";List<ApplicationCategory> result=[];await using SqliteDataReader r=await cmd.ExecuteReaderAsync(cancellationToken).ConfigureAwait(false);while(await r.ReadAsync(cancellationToken).ConfigureAwait(false))result.Add(new(r.GetString(0),r.GetString(1),r.GetInt32(2),r.GetInt32(3)!=0,Date(r,4),Date(r,5)));return result;}
    public async Task SetCategoriesAsync(string libraryItemId,IReadOnlyCollection<LibraryItemApplicationCategory> categories,CancellationToken cancellationToken=default){await using SqliteConnection c=await factory.OpenAsync(cancellationToken).ConfigureAwait(false);await using SqliteTransaction tx=(SqliteTransaction)await c.BeginTransactionAsync(cancellationToken).ConfigureAwait(false);await using(SqliteCommand delete=c.CreateCommand()){delete.Transaction=tx;delete.CommandText="DELETE FROM LibraryItemApplicationCategories WHERE LibraryItemId=$id AND Source<>$user;";Add(delete,"$id",libraryItemId);Add(delete,"$user",(int)ApplicationCategorySource.User);await delete.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);}foreach(LibraryItemApplicationCategory category in categories)await SetCategoryAsync(c,tx,libraryItemId,category.CategoryId,category.Source,cancellationToken,category.IsPrimary).ConfigureAwait(false);await tx.CommitAsync(cancellationToken).ConfigureAwait(false);}
    public async Task SetDesktopControlAssignmentAsync(DesktopControlAssignment?assignment,string libraryItemId,CancellationToken cancellationToken=default){await using SqliteConnection c=await factory.OpenAsync(cancellationToken).ConfigureAwait(false);if(assignment is null){await using SqliteCommand delete=c.CreateCommand();delete.CommandText="DELETE FROM LibraryItemDesktopControlProfiles WHERE LibraryItemId=$id;";Add(delete,"$id",libraryItemId);await delete.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);return;}await using SqliteTransaction tx=(SqliteTransaction)await c.BeginTransactionAsync(cancellationToken).ConfigureAwait(false);await UpsertAssignmentAsync(c,tx,assignment,cancellationToken).ConfigureAwait(false);await tx.CommitAsync(cancellationToken).ConfigureAwait(false);}
    public async Task SaveDesktopControlProfileAsync(DesktopControlProfile profile,CancellationToken cancellationToken=default){await using SqliteConnection c=await factory.OpenAsync(cancellationToken).ConfigureAwait(false);await using SqliteCommand cmd=c.CreateCommand();cmd.CommandText="INSERT INTO DesktopControlProfiles(Id,Name,Enabled,CursorSensitivity,CursorAcceleration,CursorDeadzone,ScrollSensitivity,LeftClickAction,RightClickAction,MiddleClickAction,ScrollAction,BackAction,ForwardAction,EscapeAction,ToggleAction,EmergencyDisableAction,PauseOnPhysicalMouseInput,UserManaged,CreatedAtUtc,UpdatedAtUtc) VALUES($id,$name,$enabled,$sensitivity,$acceleration,$deadzone,$scroll,$left,$right,$middle,$scrollAction,$back,$forward,$escape,$toggle,$emergency,$pause,$managed,$created,$updated) ON CONFLICT(Id) DO UPDATE SET Name=excluded.Name,Enabled=excluded.Enabled,CursorSensitivity=excluded.CursorSensitivity,CursorAcceleration=excluded.CursorAcceleration,CursorDeadzone=excluded.CursorDeadzone,ScrollSensitivity=excluded.ScrollSensitivity,PauseOnPhysicalMouseInput=excluded.PauseOnPhysicalMouseInput,UpdatedAtUtc=excluded.UpdatedAtUtc;";ProfileParams(cmd,profile);await cmd.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);}
    public async Task<DesktopControlProfileResolution>ResolveForItemAsync(string libraryItemId,CancellationToken cancellationToken=default){await using SqliteConnection c=await factory.OpenAsync(cancellationToken).ConfigureAwait(false);await using SqliteCommand cmd=c.CreateCommand();cmd.CommandText="SELECT p.*,a.EnableOnLaunch FROM LibraryItemDesktopControlProfiles a JOIN DesktopControlProfiles p ON p.Id=a.DesktopControlProfileId WHERE a.LibraryItemId=$id;";Add(cmd,"$id",libraryItemId);await using SqliteDataReader r=await cmd.ExecuteReaderAsync(cancellationToken).ConfigureAwait(false);return await r.ReadAsync(cancellationToken).ConfigureAwait(false)?new(ReadProfile(r),r.GetInt32(r.GetOrdinal("EnableOnLaunch"))!=0):new(null,false);}

    private static async Task<(string? Item,bool Exact)>FindDuplicateAsync(SqliteConnection c,WindowsApplicationCandidate candidate,CancellationToken ct){await using SqliteCommand cmd=c.CreateCommand();cmd.CommandText="SELECT LibraryItemId,CASE WHEN ProviderId=$provider AND ProviderItemId=$providerItem THEN 1 ELSE 0 END Exact FROM WindowsApplicationSources WHERE (ProviderId=$provider AND ProviderItemId=$providerItem) OR ($aumid IS NOT NULL AND AppUserModelId=$aumid) OR ($shortcut IS NOT NULL AND NormalizedShortcutPath=$shortcut) OR ($target IS NOT NULL AND NormalizedTargetPath=$target) OR ($browser IS NOT NULL AND BrowserFamily=$family AND BrowserAppId=$browser) ORDER BY Exact DESC LIMIT 1;";Add(cmd,"$provider",candidate.ProviderId);Add(cmd,"$providerItem",candidate.ProviderItemId);Add(cmd,"$aumid",Empty(candidate.AppUserModelId));Add(cmd,"$shortcut",Normalize(candidate.ShortcutPath));Add(cmd,"$target",Normalize(candidate.TargetPath));Add(cmd,"$browser",Empty(candidate.BrowserAppId));Add(cmd,"$family",Empty(candidate.BrowserFamily));await using SqliteDataReader r=await cmd.ExecuteReaderAsync(ct).ConfigureAwait(false);return await r.ReadAsync(ct).ConfigureAwait(false)?(r.GetString(0),r.GetInt32(1)!=0):(null,false);}
    private static async Task InsertItemAsync(SqliteConnection c,SqliteTransaction tx,string id,WindowsApplicationCandidate item,CancellationToken ct){DateTime now=DateTime.UtcNow;await using SqliteCommand cmd=c.CreateCommand();cmd.Transaction=tx;cmd.CommandText="INSERT INTO LibraryItems(Id,Title,SortTitle,Subtitle,Description,ContentType,Favorite,Hidden,AddedAtUtc,UpdatedAtUtc,TotalPlaytimeSeconds,ApplicationCardStyle) VALUES($id,$title,$title,$subtitle,$description,$type,0,0,$now,$now,0,$style);";Add(cmd,"$id",id);Add(cmd,"$title",item.DisplayName);Add(cmd,"$subtitle",item.Publisher);Add(cmd,"$description",item.Description);Add(cmd,"$type",(int)ContentType.Application);Add(cmd,"$now",now.ToString("O"));Add(cmd,"$style",(int)(item.SourceType==WindowsApplicationSourceType.ProgressiveWebApplication?ApplicationCardStyle.Square:item.SourceType==WindowsApplicationSourceType.SystemApplication?ApplicationCardStyle.Compact:ApplicationCardStyle.Wide));await cmd.ExecuteNonQueryAsync(ct).ConfigureAwait(false);}
    private static async Task InsertWindowsSourceAsync(SqliteConnection c,SqliteTransaction tx,string id,string itemId,WindowsApplicationCandidate item,CancellationToken ct){DateTime now=DateTime.UtcNow;await using SqliteCommand cmd=c.CreateCommand();cmd.Transaction=tx;cmd.CommandText="INSERT INTO WindowsApplicationSources(Id,LibraryItemId,ProviderId,ProviderItemId,SourceType,ShortcutPath,NormalizedShortcutPath,TargetPath,NormalizedTargetPath,Arguments,WorkingDirectory,AppUserModelId,PackageFamilyName,PackageFullName,ApplicationId,ProtocolUri,BrowserFamily,BrowserAppId,WebAppUrl,StartMenuFolder,CategoryHint,DiscoveryConfidence,Installed,ProviderDataJson,FirstSeenAtUtc,LastSeenAtUtc) VALUES($id,$library,$provider,$providerItem,$type,$shortcut,$normalizedShortcut,$target,$normalizedTarget,$arguments,$working,$aumid,$family,$full,$application,$uri,$browser,$browserId,$web,$folder,$category,$confidence,$installed,$data,$now,$now);";SourceParams(cmd,id,itemId,item,now);await cmd.ExecuteNonQueryAsync(ct).ConfigureAwait(false);}
    private static async Task InsertGenericSourceAsync(SqliteConnection c,SqliteTransaction tx,string itemId,WindowsApplicationCandidate item,CancellationToken ct){DateTime now=DateTime.UtcNow;await using SqliteCommand cmd=c.CreateCommand();cmd.Transaction=tx;cmd.CommandText="INSERT INTO LibraryItemSources(Id,LibraryItemId,ProviderId,ProviderItemId,InstallationPath,ManifestPath,Installed,ProviderDataJson,FirstSeenAtUtc,LastSeenAtUtc) VALUES($id,$library,$provider,$providerItem,$path,$manifest,$installed,$data,$now,$now);";Add(cmd,"$id",Guid.NewGuid().ToString("N"));Add(cmd,"$library",itemId);Add(cmd,"$provider",item.ProviderId);Add(cmd,"$providerItem",item.ProviderItemId);Add(cmd,"$path",item.TargetPath);Add(cmd,"$manifest",item.ShortcutPath);Add(cmd,"$installed",item.Installed?1:0);Add(cmd,"$data",JsonSerializer.Serialize(item.ProviderData,JsonOptions));Add(cmd,"$now",now.ToString("O"));await cmd.ExecuteNonQueryAsync(ct).ConfigureAwait(false);}
    private static async Task InsertLaunchTargetAsync(SqliteConnection c,SqliteTransaction tx,string id,string sourceId,string itemId,WindowsApplicationCandidate item,CancellationToken ct){DateTime now=DateTime.UtcNow;LaunchType type=item.LaunchMethod switch{WindowsLaunchMethod.ShellLink=>item.SourceType==WindowsApplicationSourceType.ProgressiveWebApplication?LaunchType.BrowserApplication:LaunchType.WindowsShortcut,WindowsLaunchMethod.AppUserModelId=>LaunchType.PackagedApplication,WindowsLaunchMethod.Uri=>LaunchType.Uri,WindowsLaunchMethod.ShellItem=>LaunchType.ShellItem,WindowsLaunchMethod.BrowserApplication=>LaunchType.BrowserApplication,_=>LaunchType.Executable};ApplicationTrackingMode tracking=item.SourceType==WindowsApplicationSourceType.ProgressiveWebApplication?ApplicationTrackingMode.None:item.SourceType==WindowsApplicationSourceType.PackagedApplication?ApplicationTrackingMode.ActivatedProcessHint:ApplicationTrackingMode.LaunchedProcess;bool classic=tracking==ApplicationTrackingMode.LaunchedProcess;await using SqliteCommand cmd=c.CreateCommand();cmd.Transaction=tx;cmd.CommandText="INSERT INTO LaunchTargets(Id,LibraryItemId,Name,LaunchType,ExecutablePath,ShortcutPath,WorkingDirectory,Arguments,Uri,ExpectedProcessName,HideFrontendWhileRunning,RestoreFrontendAfterExit,CreatedAtUtc,UpdatedAtUtc,ProviderId,IsEnabled,UserManaged,ArgumentListJson,EnvironmentOverridesJson,WindowsApplicationSourceId,WindowsLaunchMethod,AppUserModelId,ShellParsingPath,TrackingMode,ExpectedExecutablePath,DetectionTimeoutSeconds,ExitGracePeriodSeconds) VALUES($id,$item,$name,$type,$exe,$shortcut,$working,$arguments,$uri,$process,$hide,$restore,$now,$now,$provider,$enabled,0,$argumentList,'{}',$source,$method,$aumid,$shell,$tracking,$expected,30,3);";Add(cmd,"$id",id);Add(cmd,"$item",itemId);Add(cmd,"$name",item.SourceType==WindowsApplicationSourceType.ProgressiveWebApplication?"Installed Web App":item.LaunchMethod.ToString());Add(cmd,"$type",(int)type);Add(cmd,"$exe",item.TargetPath);Add(cmd,"$shortcut",item.ShortcutPath);Add(cmd,"$working",item.WorkingDirectory);Add(cmd,"$arguments",item.UnresolvedArguments);Add(cmd,"$uri",item.ProtocolUri?.AbsoluteUri);Add(cmd,"$process",item.TargetPath is null?null:Path.GetFileNameWithoutExtension(item.TargetPath));Add(cmd,"$hide",classic?1:0);Add(cmd,"$restore",classic?1:0);Add(cmd,"$now",now.ToString("O"));Add(cmd,"$provider",item.ProviderId);Add(cmd,"$enabled",item.Installed?1:0);Add(cmd,"$argumentList",JsonSerializer.Serialize(item.Arguments,JsonOptions));Add(cmd,"$source",sourceId);Add(cmd,"$method",(int)item.LaunchMethod);Add(cmd,"$aumid",item.AppUserModelId);Add(cmd,"$shell",item.ShellParsingPath);Add(cmd,"$tracking",(int)tracking);Add(cmd,"$expected",item.TargetPath);await cmd.ExecuteNonQueryAsync(ct).ConfigureAwait(false);await using SqliteCommand set=c.CreateCommand();set.Transaction=tx;set.CommandText="UPDATE LibraryItems SET DefaultLaunchTargetId=COALESCE(DefaultLaunchTargetId,$target) WHERE Id=$item;";Add(set,"$target",id);Add(set,"$item",itemId);await set.ExecuteNonQueryAsync(ct).ConfigureAwait(false);}
    private static async Task UpdateSourceAsync(SqliteConnection c,SqliteTransaction tx,WindowsApplicationCandidate item,CancellationToken ct){DateTime now=DateTime.UtcNow;await using SqliteCommand cmd=c.CreateCommand();cmd.Transaction=tx;cmd.CommandText="UPDATE WindowsApplicationSources SET ShortcutPath=$shortcut,NormalizedShortcutPath=$normalizedShortcut,TargetPath=$target,NormalizedTargetPath=$normalizedTarget,Arguments=$arguments,WorkingDirectory=$working,AppUserModelId=$aumid,PackageFamilyName=$family,PackageFullName=$full,ApplicationId=$application,ProtocolUri=$uri,BrowserFamily=$browser,BrowserAppId=$browserId,WebAppUrl=$web,StartMenuFolder=$folder,CategoryHint=$category,DiscoveryConfidence=$confidence,Installed=$installed,ProviderDataJson=$data,LastSeenAtUtc=$now WHERE ProviderId=$provider AND ProviderItemId=$providerItem; UPDATE LibraryItemSources SET InstallationPath=$target,ManifestPath=$shortcut,Installed=$installed,LastSeenAtUtc=$now WHERE ProviderId=$provider AND ProviderItemId=$providerItem; UPDATE LaunchTargets SET IsEnabled=$installed,ExecutablePath=$target,ShortcutPath=$shortcut,AppUserModelId=$aumid,ShellParsingPath=$shell,ArgumentListJson=$argumentList,UpdatedAtUtc=$now WHERE WindowsApplicationSourceId IN(SELECT Id FROM WindowsApplicationSources WHERE ProviderId=$provider AND ProviderItemId=$providerItem) AND UserManaged=0;";Add(cmd,"$shortcut",item.ShortcutPath);Add(cmd,"$normalizedShortcut",Normalize(item.ShortcutPath));Add(cmd,"$target",item.TargetPath);Add(cmd,"$normalizedTarget",Normalize(item.TargetPath));Add(cmd,"$arguments",JsonSerializer.Serialize(item.Arguments,JsonOptions));Add(cmd,"$working",item.WorkingDirectory);Add(cmd,"$aumid",item.AppUserModelId);Add(cmd,"$family",item.PackageFamilyName);Add(cmd,"$full",item.PackageFullName);Add(cmd,"$application",item.ApplicationId);Add(cmd,"$uri",item.ProtocolUri?.AbsoluteUri);Add(cmd,"$browser",item.BrowserFamily);Add(cmd,"$browserId",item.BrowserAppId);Add(cmd,"$web",item.WebAppUrl?.AbsoluteUri);Add(cmd,"$folder",item.StartMenuFolder);Add(cmd,"$category",item.CategoryHint);Add(cmd,"$confidence",(int)item.DiscoveryConfidence);Add(cmd,"$installed",item.Installed?1:0);Add(cmd,"$data",JsonSerializer.Serialize(item.ProviderData,JsonOptions));Add(cmd,"$now",now.ToString("O"));Add(cmd,"$provider",item.ProviderId);Add(cmd,"$providerItem",item.ProviderItemId);Add(cmd,"$shell",item.ShellParsingPath);Add(cmd,"$argumentList",JsonSerializer.Serialize(item.Arguments,JsonOptions));await cmd.ExecuteNonQueryAsync(ct).ConfigureAwait(false);}
    private static async Task UpsertTrackingAsync(SqliteConnection c,SqliteTransaction tx,string itemId,WindowsApplicationCandidate item,CancellationToken ct){ApplicationTrackingMode mode=item.SourceType==WindowsApplicationSourceType.ProgressiveWebApplication?ApplicationTrackingMode.None:item.SourceType==WindowsApplicationSourceType.PackagedApplication?ApplicationTrackingMode.ActivatedProcessHint:ApplicationTrackingMode.LaunchedProcess;await using SqliteCommand cmd=c.CreateCommand();cmd.Transaction=tx;cmd.CommandText="INSERT OR IGNORE INTO ApplicationLaunchTracking(LibraryItemId,TrackingMode,ExpectedProcessName,ExpectedExecutablePath,ExpectedAppUserModelId,ExpectedWindowClass,DetectionTimeoutSeconds,ExitGracePeriodSeconds,UserManaged,UpdatedAtUtc) VALUES($item,$mode,$process,$path,$aumid,NULL,30,3,0,$now);";Add(cmd,"$item",itemId);Add(cmd,"$mode",(int)mode);Add(cmd,"$process",item.TargetPath is null?null:Path.GetFileNameWithoutExtension(item.TargetPath));Add(cmd,"$path",item.TargetPath);Add(cmd,"$aumid",item.AppUserModelId);Add(cmd,"$now",DateTime.UtcNow.ToString("O"));await cmd.ExecuteNonQueryAsync(ct).ConfigureAwait(false);}
    private static async Task SetCategoryAsync(SqliteConnection c,SqliteTransaction tx,string itemId,string categoryId,ApplicationCategorySource source,CancellationToken ct,bool primary=true){await using SqliteCommand cmd=c.CreateCommand();cmd.Transaction=tx;if(primary&&source!=ApplicationCategorySource.User){cmd.CommandText="SELECT COUNT(*) FROM LibraryItemApplicationCategories WHERE LibraryItemId=$item AND IsPrimary=1 AND Source=$user;";Add(cmd,"$item",itemId);Add(cmd,"$user",(int)ApplicationCategorySource.User);primary=Convert.ToInt32(await cmd.ExecuteScalarAsync(ct).ConfigureAwait(false),CultureInfo.InvariantCulture)==0;cmd.Parameters.Clear();}if(primary){cmd.CommandText=source==ApplicationCategorySource.User?"UPDATE LibraryItemApplicationCategories SET IsPrimary=0 WHERE LibraryItemId=$item;":"UPDATE LibraryItemApplicationCategories SET IsPrimary=0 WHERE LibraryItemId=$item AND Source<>$user;";Add(cmd,"$item",itemId);Add(cmd,"$user",(int)ApplicationCategorySource.User);await cmd.ExecuteNonQueryAsync(ct).ConfigureAwait(false);cmd.Parameters.Clear();}cmd.CommandText="INSERT INTO LibraryItemApplicationCategories(LibraryItemId,CategoryId,IsPrimary,Source) VALUES($item,$category,$primary,$source) ON CONFLICT(LibraryItemId,CategoryId) DO UPDATE SET IsPrimary=CASE WHEN Source=$user THEN IsPrimary ELSE excluded.IsPrimary END,Source=CASE WHEN Source=$user THEN Source ELSE excluded.Source END;";Add(cmd,"$item",itemId);Add(cmd,"$category",categoryId);Add(cmd,"$primary",primary?1:0);Add(cmd,"$source",(int)source);Add(cmd,"$user",(int)ApplicationCategorySource.User);await cmd.ExecuteNonQueryAsync(ct).ConfigureAwait(false);}
